// Functional schematics: component geometry is explanatory, never a mass estimate.
export function diagram(type,selected,parts){
 const group=(i,body)=>`<g class="diagram-part ${selected===i?'chosen':''}" data-part="${i}" role="button" tabindex="0" aria-label="${parts[i][0]}" aria-pressed="${selected===i}">${body}</g>`;
 let body='';
 if(type==='ev')body=group(0,'<path d="M75 155 123 120H350L415 157 457 166V209H59V173Z"/><path d="M144 121 179 71H296L345 121Z"/><path d="M197 77V114M274 77 299 114" fill="none"/><circle cx="130" cy="211" r="27"/><circle cx="385" cy="211" r="27"/><text x="220" y="93">01</text>')+group(1,'<path d="M147 256 189 237H344L304 278H147Z"/><path d="M147 256V271L303 294 344 253V237" fill="none"/><text x="210" y="270">02</text>')+group(2,'<rect x="391" y="267" width="72" height="46" rx="14"/><path d="M389 290H373M463 290H482"/><text x="416" y="295">03</text>')+group(3,'<rect x="71" y="47" width="65" height="39" rx="4"/><path d="M80 56H121V76H80Z"/><text x="82" y="33">04</text>')+'<path class="guide" d="M104 87V136M237 213V236M419 212V262"/>';
 if(type==='battery')body=parts.map((p,i)=>group(i,`<path d="M${65+i*19} ${52+i*45} 355 ${32+i*45} 426 ${66+i*45} ${134+i*19} ${87+i*45}Z"/><text x="${82+i*19}" y="${65+i*45}">0${i+1}</text><path class="guide" d="M426 ${66+i*45}H463"/><text x="470" y="${70+i*45}">${i===0?'−':i===4?'+':''}</text>`)).join('');
 if(type==='solar')body=parts.map((p,i)=>group(i,`<path d="M${66+i*22} ${45+i*55} 354 ${26+i*55} 435 ${69+i*55} ${146+i*22} ${90+i*55}Z" ${i===3?'fill="none" stroke-width="5"':''}/>${i===1?'<path d="M143 110 392 94M181 141 125 111M238 137 182 107M295 133 239 103M352 130 296 99" fill="none"/>':''}<text x="${80+i*22}" y="${61+i*55}">0${i+1}</text>`)).join('');
 if(type==='wind')body=group(2,'<path d="M249 162 237 330H271L260 162Z"/><text x="244" y="267">03</text>')+group(3,'<path d="M258 176V321L329 343" fill="none" stroke-width="6"/><text x="323" y="327">04</text>')+group(1,'<rect x="260" y="131" width="112" height="46" rx="12"/><circle cx="326" cy="153" r="15"/><text x="351" y="115">02</text>')+group(0,'<path d="M249 151 232 29 248 16 263 131Z M240 159 117 216 97 210 223 147Z M258 161 345 245 342 266 247 180Z"/><circle cx="249" cy="154" r="16"/><text x="168" y="91">01</text>');
 return `<svg viewBox="0 0 540 360" class="exploded-diagram" role="group" aria-label="Vista esquemática com componentes selecionáveis">${body}</svg>`;
}
